messageValues.message:
Generate A/B test ideas for: {{ $json.industry || 'e-commerce' }}
Business goal: {{ $json.goal || 'increase conversions' }}
Target page: {{ $json.page || 'product page' }}
Current conversion rate: {{ $json.currentRate || '2.5%' }}
Traffic per month: {{ $json.traffic || '10000' }}

Provide 3 test ideas with different approaches and complexity levels.

parameters.jsCode:
// Process and structure A/B test hypotheses
const aiResponse = $input.first().json.message.content;
const inputData = $('Webhook Trigger').first().json.body;

try {
  const testIdeas = parseTestIdeas(aiResponse);

  // Add statistical calculations for each test
  const enrichedTests = testIdeas.map((test, index) => {
    const stats = calculateTestRequirements(
      parseFloat(inputData.currentRate) || 2.5,
      parseFloat(inputData.traffic) || 10000,
      test.expectedLift || 20
    );

    return {
      id: `test_${Date.now()}_${index}`,
      ...test,
      statistics: stats,
      timestamp: new Date().toISOString()
    };
  });

  return [{
    testIdeas: enrichedTests,
    summary: {
      totalTests: enrichedTests.length,
      avgDuration: Math.round(enrichedTests.reduce((sum, t) => sum + t.statistics.duration95, 0) / enrichedTests.length),
      industry: inputData.industry || 'e-commerce'
    }
  }];
} catch (error) {
  return [{
    error: true,
    message: 'Failed to process test ideas',
    details: error.message
  }];
}

function parseTestIdeas(response) {
  // Parse AI response into structured test ideas
  const sections = response.split(/Test\s*\d+:|Idea\s*\d+:/).slice(1);

  return sections.map(section => {
    return {
      hypothesis: extractField(section, 'Hypothesis:|If'),
      objective: extractField(section, 'Objective:|Primary objective'),
      testType: extractField(section, 'Test type:|Type'),
      targetAudience: extractField(section, 'Target audience:|Audience'),
      expectedLift: extractNumber(section, 'Expected impact:|Impact') || 20,
      confidence: extractNumber(section, 'Confidence level:|Confidence') || 80,
      risks: extractField(section, 'Risks:|Potential risks'),
      resources: extractField(section, 'Resources:|Resource requirements'),
      timeline: extractField(section, 'Timeline:|Timeline recommendations')
    };
  });
}

function extractField(text, pattern) {
  const regex = new RegExp(pattern + '\\s*([^\\n]+(?:\\n(?!\\w+:)[^\\n]*)*)', 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : '';
}

function extractNumber(text, pattern) {
  const field = extractField(text, pattern);
  const numberMatch = field.match(/\d+(?:\.\d+)?/);
  return numberMatch ? parseFloat(numberMatch[0]) : null;
}

function calculateTestRequirements(baselineRate, monthlyTraffic, expectedLift) {
  const baseline = baselineRate / 100;
  const treatment = baseline * (1 + expectedLift / 100);
  const alpha = 0.05; // 95% confidence
  const beta = 0.2;   // 80% power

  // Sample size calculation using normal approximation
  const pooledRate = (baseline + treatment) / 2;
  const effect = Math.abs(treatment - baseline);

  const z_alpha = 1.96; // 95% confidence
  const z_beta = 0.84;  // 80% power

  const sampleSizePerVariation = Math.ceil(
    (2 * pooledRate * (1 - pooledRate) * Math.pow(z_alpha + z_beta, 2)) / Math.pow(effect, 2)
  );

  const totalSampleSize = sampleSizePerVariation * 2;
  const durationDays90 = Math.ceil((totalSampleSize * 30) / monthlyTraffic);
  const durationDays95 = Math.ceil(durationDays90 * 1.3); // More conservative for 95%

  return {
    sampleSizePerVariation,
    totalSampleSize,
    duration90: durationDays90,
    duration95: durationDays95,
    baselineRate: baseline,
    treatmentRate: treatment,
    minimumDetectableEffect: effect,
    expectedLiftPercent: expectedLift
  };
}

// Advanced statistical calculator for A/B tests
const input = $('Webhook Trigger').first().json.body;

const results = {
  inputParams: {
    baselineRate: parseFloat(input.baselineRate) || 2.5,
    expectedLift: parseFloat(input.expectedLift) || 20,
    monthlyTraffic: parseInt(input.monthlyTraffic) || 10000,
    confidence: parseFloat(input.confidence) || 95,
    power: parseFloat(input.power) || 80
  }
};

// Calculate sample sizes for different confidence levels
results.calculations = {
  confidence90: calculateSampleSize(results.inputParams, 90, 80),
  confidence95: calculateSampleSize(results.inputParams, 95, 80),
  confidence99: calculateSampleSize(results.inputParams, 99, 80)
};

// Risk analysis
results.riskAnalysis = {
  type1Error: (100 - results.inputParams.confidence) / 100,
  type2Error: (100 - results.inputParams.power) / 100,
  recommendations: generateRecommendations(results.inputParams, results.calculations)
};

// Cost analysis
results.costAnalysis = calculateCostAnalysis(results.calculations, input.costPerVisitor || 0.5);

return [results];

function calculateSampleSize(params, confidence, power) {
  const baseline = params.baselineRate / 100;
  const treatment = baseline * (1 + params.expectedLift / 100);
  const alpha = (100 - confidence) / 100;
  const beta = (100 - power) / 100;

  // Z-scores for different confidence levels
  const zScores = { 90: 1.645, 95: 1.96, 99: 2.576 };
  const z_alpha = zScores[confidence] || 1.96;
  const z_beta = 0.84; // 80% power

  const pooledRate = (baseline + treatment) / 2;
  const effect = Math.abs(treatment - baseline);

  const sampleSize = Math.ceil(
    (2 * pooledRate * (1 - pooledRate) * Math.pow(z_alpha + z_beta, 2)) / Math.pow(effect, 2)
  );

  const duration = Math.ceil((sampleSize * 2 * 30) / params.monthlyTraffic);

  return {
    sampleSizePerVariation: sampleSize,
    totalSampleSize: sampleSize * 2,
    durationDays: duration,
    durationWeeks: Math.ceil(duration / 7),
    confidenceLevel: confidence,
    powerLevel: power,
    minimumDetectableEffect: (effect * 100).toFixed(2) + '%'
  };
}

function generateRecommendations(params, calculations) {
  const recommendations = [];

  if (calculations.confidence95.durationDays > 60) {
    recommendations.push('Consider increasing expected lift or traffic to reduce test duration');
  }

  if (params.baselineRate < 1) {
    recommendations.push('Low baseline rate detected - consider focusing on traffic quality first');
  }

  if (calculations.confidence95.sampleSizePerVariation > params.monthlyTraffic) {
    recommendations.push('Sample size exceeds monthly traffic - consider multi-month test or traffic increase');
  }

  return recommendations;
}

function calculateCostAnalysis(calculations, costPerVisitor) {
  const conf95 = calculations.confidence95;
  return {
    costPerVisitor,
    totalTestCost: (conf95.totalSampleSize * costPerVisitor).toFixed(2),
    costPerDay: ((conf95.totalSampleSize * costPerVisitor) / conf95.durationDays).toFixed(2),
    estimatedROI: calculateROI(conf95.totalSampleSize, costPerVisitor)
  };
}

function calculateROI(sampleSize, costPerVisitor) {
  // Simplified ROI calculation
  const testCost = sampleSize * costPerVisitor;
  const estimatedLiftValue = sampleSize * 0.025 * 50; // Assume $50 avg order value
  const roi = ((estimatedLiftValue - testCost) / testCost * 100).toFixed(1);
  return roi + '%';
}

messageValues.message:
Create wireframe designs for A/B test:
Hypothesis: {{ $json.hypothesis }}
Test Type: {{ $json.testType }}
Page Type: {{ $json.pageType }}
Primary Goal: {{ $json.goal }}
Target Element: {{ $json.element }}

Provide control and variation designs with HTML/CSS code snippets.

parameters.jsCode:
// Process wireframe designs and generate implementable code
const aiResponse = $input.first().json.message.content;
const inputData = $('Webhook Trigger').first().json.body;

const wireframes = {
  testId: `wireframe_${Date.now()}`,
  hypothesis: inputData.hypothesis,
  variations: parseWireframes(aiResponse),
  implementationGuide: {
    setupInstructions: extractImplementationNotes(aiResponse),
    trackingCode: generateTrackingCode(inputData.goal),
    cssFramework: 'vanilla', // or detect from requirements
    estimatedDevTime: '4-8 hours'
  },
  qualityChecklist: [
    'Mobile responsive design verified',
    'Accessibility standards (WCAG 2.1) compliance',
    'Cross-browser compatibility tested',
    'Loading performance optimized',
    'Analytics tracking implemented',
    'QA testing completed'
  ]
};

return [wireframes];

function parseWireframes(response) {
  // Extract control and variation designs
  const variations = [];

  // Look for Control and Variation sections
  const controlMatch = response.match(/(?:Control|Original)([\s\S]*?)(?=Variation|$)/i);
  const variationMatches = response.match(/Variation[\s\S]*?(?=Variation|Implementation|$)/gi);

  if (controlMatch) {
    variations.push({
      name: 'Control',
      type: 'control',
      description: extractDescription(controlMatch[1]),
      htmlCode: extractCode(controlMatch[1], 'html'),
      cssCode: extractCode(controlMatch[1], 'css'),
      keyFeatures: extractFeatures(controlMatch[1])
    });
  }

  if (variationMatches) {
    variationMatches.forEach((variation, index) => {
      variations.push({
        name: `Variation ${String.fromCharCode(65 + index)}`,
        type: 'treatment',
        description: extractDescription(variation),
        htmlCode: extractCode(variation, 'html'),
        cssCode: extractCode(variation, 'css'),
        keyFeatures: extractFeatures(variation),
        expectedImpact: extractExpectedImpact(variation)
      });
    });
  }

  return variations;
}

function extractDescription(text) {
  const lines = text.split('\n').slice(0, 5);
  return lines.join('\n').trim();
}

function extractCode(text, type) {
  const pattern = new RegExp(`\`\`\`${type}([\s\S]*?)\`\`\``, 'i');
  const match = text.match(pattern);
  return match ? match[1].trim() : '';
}

function extractFeatures(text) {
  const features = [];
  const lines = text.split('\n');

  lines.forEach(line => {
    if (line.match(/^[-•*]\s/) || line.match(/^\d+\.\s/)) {
      features.push(line.replace(/^[-•*\d.\s]+/, '').trim());
    }
  });

  return features.slice(0, 5); // Limit to 5 key features
}

function extractExpectedImpact(text) {
  const impactMatch = text.match(/(?:impact|expect|improve)[\s:]*([^\n]+)/i);
  return impactMatch ? impactMatch[1].trim() : 'Improved user engagement';
}

function extractImplementationNotes(text) {
  const notesMatch = text.match(/(?:implementation|notes|setup)([\s\S]*?)$/i);
  return notesMatch ? notesMatch[1].trim() : 'Standard A/B test implementation';
}

function generateTrackingCode(goal) {
  return `
// A/B Test Tracking Code
(function() {
  // Track test exposure
  gtag('event', 'ab_test_exposure', {
    'test_name': '${goal.replace(/\s+/g, '_').toLowerCase()}',
    'variation': 'VARIATION_NAME',
    'user_id': 'USER_ID'
  });

  // Track conversion goal
  function trackConversion() {
    gtag('event', 'ab_test_conversion', {
      'test_name': '${goal.replace(/\s+/g, '_').toLowerCase()}',
      'variation': 'VARIATION_NAME',
      'value': 1
    });
  }

  // Attach to relevant elements
  document.addEventListener('click', function(e) {
    if (e.target.matches('.cta-button, .conversion-trigger')) {
      trackConversion();
    }
  });
})();
`;
}
